sp_page.css:
/* 1. Centraliza e diminui a largura da tabela */
.row {
    display: flex;
    justify-content: center;
    padding: 60px 0;
}

.col-md-12 {
    max-width: 900px; /* Impede que a tabela fique gigante na tela */
}

/* 2. Estilo do Card (Tabela) */
.panel {
    background-color: rgba(255, 255, 255, 0.9) !important; /* Branco levemente transparente */
    backdrop-filter: blur(5px); /* Efeito de vidro embaçado no fundo */
    border: none !important;
    border-radius: 15px !important;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5) !important;
    overflow: hidden;
}

/* 3. Cabeçalho da Tabela */
.panel-heading {
    background-color: #002b3d !important; /* Azul Shark */
    padding: 20px !important;
    border: none !important;
}

/* 4. Ajuste das linhas para não parecerem "amontoadas" */
.table > tbody > tr > td {
    padding: 15px !important;
    vertical-align: middle !important;
    border-color: rgba(0, 0, 0, 0.05) !important;
}

/* 5. Efeito de destaque ao passar o mouse */
.table > tbody > tr:hover {
    background-color: rgba(0, 118, 168, 0.05) !important;
    cursor: pointer;
}
